CREATE TABLE public.member_connections(session_id uuid PRIMARY KEY,member_id uuid NOT NULL REFERENCES public.members(id) ON DELETE CASCADE,token_hash text NOT NULL,last_seen_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
GRANT ALL ON public.member_connections TO service_role;
ALTER TABLE public.member_connections ENABLE ROW LEVEL SECURITY;
CREATE INDEX member_connections_member_idx ON public.member_connections(member_id);
CREATE TABLE public.manager_emails(email text PRIMARY KEY);
GRANT ALL ON public.manager_emails TO service_role;
ALTER TABLE public.manager_emails ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role='manager'),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE FUNCTION public.is_manager() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='manager'); $$;
REVOKE ALL ON FUNCTION public.is_manager() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_manager() TO authenticated;
CREATE FUNCTION public.assign_confirmed_manager() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.manager_emails WHERE email=lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'manager') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER stoneverso_manager_confirmed AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_confirmed_manager();
CREATE FUNCTION public.connect_member(p_name text,p_member uuid,p_token text,p_session uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid;v_hash text;v_active boolean; BEGIN
IF p_token IS NULL OR length(p_token)<32 OR length(p_token)>200 THEN RAISE EXCEPTION 'Invalid token'; END IF;
v_hash:=encode(sha256(convert_to(p_token,'UTF8')),'hex');
IF p_name IS NOT NULL THEN
IF length(trim(p_name)) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Invalid name'; END IF;
INSERT INTO public.members(display_name) VALUES(trim(p_name)) ON CONFLICT(lower(trim(display_name))) DO UPDATE SET display_name=public.members.display_name RETURNING id INTO v_id;
ELSE v_id:=p_member; IF NOT EXISTS(SELECT 1 FROM public.member_connections WHERE member_id=v_id AND token_hash=v_hash) THEN RAISE EXCEPTION 'Unknown device'; END IF; END IF;
PERFORM 1 FROM public.members WHERE id=v_id FOR UPDATE;
SELECT EXISTS(SELECT 1 FROM public.member_connections WHERE member_id=v_id AND closed_at IS NULL AND last_seen_at>now()-interval '3 minutes') INTO v_active;
INSERT INTO public.member_connections(session_id,member_id,token_hash) VALUES(p_session,v_id,v_hash) ON CONFLICT(session_id) DO UPDATE SET last_seen_at=now(),closed_at=NULL WHERE member_connections.member_id=v_id AND member_connections.token_hash=v_hash;
IF NOT FOUND THEN RAISE EXCEPTION 'Invalid session'; END IF;
IF NOT v_active THEN UPDATE public.members SET status='online',status_updated_at=now() WHERE id=v_id; END IF;
RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.connect_member(text,uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.connect_member(text,uuid,text,uuid) TO anon,authenticated;
CREATE FUNCTION public.heartbeat_member(p_session uuid,p_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.member_connections SET last_seen_at=now(),closed_at=NULL WHERE session_id=p_session AND token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex'); IF NOT FOUND THEN RAISE EXCEPTION 'Invalid session'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.heartbeat_member(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.heartbeat_member(uuid,text) TO anon,authenticated;
CREATE FUNCTION public.close_member(p_session uuid,p_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN SELECT member_id INTO v_id FROM public.member_connections WHERE session_id=p_session AND token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex'); IF v_id IS NULL THEN RETURN; END IF; PERFORM 1 FROM public.members WHERE id=v_id FOR UPDATE; UPDATE public.member_connections SET closed_at=now() WHERE session_id=p_session; IF NOT EXISTS(SELECT 1 FROM public.member_connections WHERE member_id=v_id AND closed_at IS NULL AND last_seen_at>now()-interval '3 minutes') THEN UPDATE public.members SET status='offline' WHERE id=v_id; END IF; END; $$;
REVOKE ALL ON FUNCTION public.close_member(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.close_member(uuid,text) TO anon,authenticated;
CREATE FUNCTION public.set_member_status(p_session uuid,p_token text,p_status public.presence_status) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN SELECT member_id INTO v_id FROM public.member_connections WHERE session_id=p_session AND closed_at IS NULL AND token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex'); IF v_id IS NULL THEN RAISE EXCEPTION 'Invalid session'; END IF; UPDATE public.members SET status=p_status WHERE id=v_id; END; $$;
REVOKE ALL ON FUNCTION public.set_member_status(uuid,text,public.presence_status) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_member_status(uuid,text,public.presence_status) TO anon,authenticated;
CREATE FUNCTION public.manager_set_status(p_member uuid,p_status public.presence_status) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; UPDATE public.members SET status=p_status WHERE id=p_member; IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.manager_set_status(uuid,public.presence_status) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.manager_set_status(uuid,public.presence_status) TO authenticated;
CREATE FUNCTION public.list_member_presence() RETURNS SETOF public.members LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,m.display_name,CASE WHEN c.active THEN m.status ELSE 'offline'::public.presence_status END,CASE WHEN c.active OR m.status='offline' THEN m.status_updated_at ELSE coalesce(c.ended,m.status_updated_at) END,m.created_at FROM public.members m LEFT JOIN LATERAL(SELECT bool_or(closed_at IS NULL AND last_seen_at>now()-interval '3 minutes') AS active,max(coalesce(closed_at,last_seen_at+interval '3 minutes')) AS ended FROM public.member_connections WHERE member_id=m.id)c ON true; $$;
REVOKE ALL ON FUNCTION public.list_member_presence() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_member_presence() TO anon,authenticated;
COMMENT ON TABLE public.member_connections IS 'Per-tab capability leases; derive Offline after three minutes without heartbeat; tokens stored as hashes.';